// Snowflake ids for new issues (QA-CONTRACTS §4): ((ms - Discord epoch) << 22) | (worker 31 << 17) | seq.
// Same shape as Discord ids, so apply-fix.sh's ^[0-9]{15,25}$ check and fixes/<id>/ keep working, and worker 31 never
// collides with an imported thread id generated by Discord's own workers in the same ms.
export const DISCORD_EPOCH = 1420070400000n;
export const WORKER = 31n;
export const ISSUE_ID_RE = /^[0-9]{15,25}$/;

let lastMs = -1n;
let seq = 0n;

export function snowflake(now = Date.now()) {
  let ms = BigInt(now);
  if (ms < lastMs) ms = lastMs; // clock went back: keep monotonic
  if (ms === lastMs) {
    seq = (seq + 1n) & 0x1ffffn;
    if (seq === 0n) ms = lastMs + 1n; // 131072 ids in one ms: borrow the next ms
  } else seq = 0n;
  lastMs = ms;
  return (((ms - DISCORD_EPOCH) << 22n) | (WORKER << 17n) | seq).toString();
}

export const snowflakeTime = (id) => Number((BigInt(id) >> 22n) + DISCORD_EPOCH);
